if(s.operation==='minimum'){const values=[0,1];for(let h=1;h<=s.limit;h++)values.push(1+values[h]+values[h-1]);for(let h=0;h<=s.limit;h++)states.push({kind:'minimum',height:h,values:values.slice(1,h+2),action:'Establish the exact threshold at height '+h+'.',why:h?'Attach a root to minimal height-(h-1) and height-(h-2) children.':'The empty threshold is zero and the singleton threshold is one.',formula:'M_{'+h+'}='+values[h+1],complete:true});return{spec:s,states,result:{minimumByHeight:values.slice(1),emptyMinimum:0}};}
if(s.operation==='encoding'){root=node(40);root.left=node(20,true);root.right=node(60,true);refresh(root);states.push({kind:'encoding',tree:cp(root),active:[],action:'Inspect the general red-black three-key cluster.',why:'Black 40 with two red children is valid in the general variant, but is a persistent four-node forbidden in completed 2-3 LLRB.',complete:true,counters:counters()});states.push({kind:'encoding',box:true,tree:cp(root),active:[20,40,60],action:'Collapse the red links into one multiway node.',why:'The ordered cluster has keys 20,40,60 and four external interval links.',complete:true,counters:counters()});return{spec:s,states,result:{generalRedBlack:rb(root),completedLLRB:rb(root,true),keys:inorder(root),beta:1}};}
