if(z.kind==='minimum'){b+=txt(35,44,'Exact minimum nodes; bar width uses log2(M + 1).');const vals=z.values,max=Math.log2(vals.at(-1)+1);for(let i=0;i<vals.length;i++){const y=65+i*18;b+=txt(35,y+12,'h = '+i,'bl-meta')+'<rect x="95" y="'+y+'" width="'+(Math.log2(vals[i]+1)/max*460)+'" height="12" rx="3" fill="#377c83"/>'+txt(580,y+12,vals[i],'bl-meta');}return b+'</svg>';}
