const keys=[...new Set((s.keys||[]).concat(inorder(z.tree)))].sort((a,b)=>a-b),pos={},nodes=[],gap=Math.min(72,260/Math.max(1,H(z.tree))),radius=keys.length>9?20:24;function walk(t,d){if(!t)return;pos[t.key]={x:30+(keys.indexOf(t.key)+.5)*545/keys.length,y:58+d*gap};nodes.push(t);walk(t.left,d+1);walk(t.right,d+1);}walk(z.tree,0);
