for(const t of nodes){const p=pos[t.key],r=red(t),color=s.operation.startsWith('llrb')||s.operation==='classical-demo'||z.kind==='encoding',active=z.active?.includes(t.key);b+='<g data-entity="balanced-entry-'+t.key+'" data-key="'+t.key+'"><circle cx="'+p.x+'" cy="'+p.y+'" r="'+radius+'" fill="'+(color?(r?'#f6ddd8':'#e0e8ee'):active?'#d7ecea':'#fff')+'" stroke="'+(color?(r?'#b85243':'#425967'):'#658d9a')+'"/>'+txt(p.x,p.y+6,t.key,'bl-math'+(String(t.key).length>3?' bl-key-long':String(t.key).length>2?' bl-key-medium':''),'middle')+'</g>';b+=txt(p.x,p.y+radius+18,color?(r?'R':'B')+' b='+black(t):'h='+H(t)+' B='+(H(t.left)-H(t.right)),'bl-meta','middle');}
